"""Execution-only exclusions for unavailable live/model prerequisites; no test substitution."""
import pytest

LIVE = {
    'orchestration/tests/test_verifier_stabilization.py::TestVerifierStabilization::test_wikipedia_adapter_retrieval',
    'orchestration/tests/test_verifier_stabilization.py::TestVerifierStabilization::test_single_claim_end_to_end_verification',
    'orchestration/tests/test_verifier_v1_stabilization.py::TestVerifierV1Stabilization::test_1_paris_capital_of_france',
    'orchestration/tests/test_verifier_v1_stabilization.py::TestVerifierV1Stabilization::test_2_eiffel_tower_in_london',
    'orchestration/tests/test_verifier_v1_stabilization.py::TestVerifierV1Stabilization::test_3_moon_made_of_green_cheese',
    'orchestration/tests/test_verifier_v1_stabilization.py::TestVerifierV1Stabilization::test_4_aspirin_mild_pain_healthcare',
}
MODELS = {
    'agents/verifier_agent/tests/test_n8n_retrieval.py::test_pipeline_uses_n8n_evidence_and_runs_python_bge_nli',
    'agents/verifier_agent/tests/test_n8n_retrieval.py::test_pipeline_fallback_to_python_adapters_on_n8n_failure',
    'agents/verifier_agent/tests/test_n8n_retrieval.py::test_no_duplicate_retrieval_when_n8n_succeeds',
    'agents/verifier_agent/tests/test_pipeline_hardening.py::TestDirectModelDiagnostics::test_direct_deberta_nli_execution',
    'agents/verifier_agent/tests/test_pipeline_hardening.py::TestDirectModelDiagnostics::test_direct_bge_reranker_execution',
}

def pytest_collection_modifyitems(items):
    for item in items:
        if item.nodeid in LIVE:
            item.add_marker(pytest.mark.skip(reason='BLOCKED/UNVERIFIED: live Verifier retrieval requires unavailable owner laptop n8n or external network; no live check is credited'))
        elif item.nodeid in MODELS:
            item.add_marker(pytest.mark.skip(reason='BLOCKED/UNVERIFIED: real Verifier BGE/DeBERTa weights are absent from the fresh offline cache; mock contract checks do not establish real-model success'))
